// 定义海南岛及周边处理范围
var bbox = ee.Geometry.Rectangle([108.5, 18.1, 111.0, 20.1]);

// GEE 中没有可直接对应的 ASTER_GDEM_DEM30 多景 DEM 集合，
// 此处使用约 30 m 分辨率的 NASADEM 作为等效 DEM 数据源。
var dem_collection = ee.ImageCollection.fromImages([
  ee.Image('NASA/NASADEM_HGT/001').select('elevation')
]).filterBounds(bbox);

// 1) DEM 合成，形成连续 DEM 表面。
// 原 OGE mosaic 的 "mean" 参数表示重叠区域取均值，
// 因此这里使用 ImageCollection.mean() 保留该统计逻辑。
var dem = dem_collection.mean().clip(bbox);

// 2) 对连续 DEM 做基础平滑：1 像元半径的方形邻域均值
var dem_base = dem.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({
    radius: 1,
    units: 'pixels',
    normalize: false
  }),
  skipMasked: true
});

// 3) 基于平滑后的 DEM 生成山体阴影。
// 保留 OGE 中传入的两个参数值：方位角 1°、太阳高度角 1°。
var hillshade = ee.Terrain.hillshade(dem_base, 1, 1);

// 可视化参数
var dem_vis = {
  min: 0,
  max: 1800,
  palette: ['#274e13', '#5b8a3c', '#b7b26a', '#d9c59a', '#f5f5f5']
};

var shade_vis = {
  min: 0,
  max: 255,
  palette: ['#1f1f1f', '#555555', '#8a8a8a', '#c0c0c0', '#f2f2f2']
};

// 输出结果：处理后的连续 DEM 与阴影结果对照展示
Map.addLayer(dem_base, dem_vis, 'dem_base');
Map.addLayer(hillshade, shade_vis, 'hillshade');

// 设置地图中心
Map.setCenter(109.7, 19.1, 9);

// 读取单景 Landsat 8 Collection 2 TOA 影像
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20151002');

// 1) 提取目标波段：全色波段 B8
var target_band = ls8.select(['B8']);

// 2) 使用参数方案 A 执行平滑处理（较轻）
var smooth_a = target_band.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels', normalize: false})
});

// 3) 使用参数方案 B 执行平滑处理（较强）
var smooth_b = target_band.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 3, units: 'pixels', normalize: false})
});

// 4) 对方案 A 结果执行统一的基础后处理
var final_a = smooth_a.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels', normalize: false})
});

// 5) 对方案 B 结果执行统一的基础后处理
var final_b = smooth_b.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels', normalize: false})
});

// LANDSAT/LC08/C02/T1_TOA 的 B8 是 TOA 反射率，通常约为 0~1。
var vis_params = {
  min: 0,
  max: 0.6,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

// 6) 组织原始波段、方案 A、方案 B 的对照图层
Map.addLayer(target_band, vis_params, 'original_band', true);
Map.addLayer(final_a, vis_params, 'version_a', false);
Map.addLayer(final_b, vis_params, 'version_b', false);

// ==================== 原始代码中的第二套显示/增强流程 ====================

// 1) 提取目标显示层
var original_display = ls8.select(['B8']);

// 2) 第一次平滑降噪
var smooth_display_1 = original_display.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square({radius: 1, units: 'pixels', normalize: false})
});

// 3) 第二次邻域优化处理
var smooth_display_2 = smooth_display_1.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels', normalize: false})
});

// 4) 细节增强，作为阶段性结果
var kernel = ee.Kernel.prewitt(true, 0.5);
var stage_display = smooth_display_2.convolve(kernel);

// 5) 对增强结果再做一次轻度整理，压一压毛躁感
var final_display = stage_display.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle({radius: 1, units: 'pixels', normalize: false})
});

var original_vis = {
  min: 0,
  max: 0.6,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

var enhance_vis = {
  min: -0.04,
  max: 0.04,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

// 原始结果、中间增强结果和最终增强结果对照展示
Map.addLayer(original_display, original_vis, 'original_display', false);
Map.addLayer(stage_display, enhance_vis, 'stage_display', false);
Map.addLayer(final_display, enhance_vis, 'final_display', false);

// 设置地图中心
Map.setCenter(115.74080156644999, 31.7318082104, 11);

// 读取单景 Landsat 8 TOA 影像
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20151002');

// 1) 提取目标波段：全色波段 B8
var target_band = ls8.select(['B8']);

// 2) 构建处理链 A：先做轻度平滑降噪
var chain_a_smooth = target_band.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square(1, 'pixels', false)
});

// 3) 在链 A 上执行 Prewitt 卷积增强
// OGE 中的 0.5 按卷积响应增益处理。
var kernel_a = ee.Kernel.prewitt(true, false);
var chain_a_final = chain_a_smooth
  .convolve(kernel_a)
  .multiply(0.5);

// 4) 构建处理链 B：直接执行 Laplacian 结构增强
var kernel_b = ee.Kernel.laplacian4();
var chain_b_enhanced = target_band.convolve(kernel_b);

// 5) 对链 B 结果执行基础后处理
var chain_b_final = chain_b_enhanced.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: ee.Kernel.circle(1, 'pixels', false)
});

// Landsat Collection 2 TOA 数据的反射率通常约为 0～1，
// 因此可视化范围相对于 OGE 原始 DN 范围进行了调整。
var original_vis = {
  min: 0,
  max: 0.3,
  palette: ['1f1f1f', '5a5a5a', '9a9a9a', 'd9d9d9', 'ffffff']
};

var enhance_vis = {
  min: -0.02,
  max: 0.02,
  palette: ['1f1f1f', '5a5a5a', '9a9a9a', 'd9d9d9', 'ffffff']
};

// 6) 将原始全色波段、链 A、链 B 加载到地图进行对照
Map.addLayer(target_band, original_vis, 'original_band');
Map.addLayer(chain_a_final, enhance_vis, 'chain_a_final');
Map.addLayer(chain_b_final, enhance_vis, 'chain_b_final');

// 设置地图中心
Map.setCenter(115.74080156644999, 31.7318082104, 11);

// 读取单景 Landsat 8 Collection 2 TOA 影像
var ls8 = ee.Image('LANDSAT/LC08/C02/T1_TOA/LC08_122038_20151002');

// 1) 提取更适合看细节的输入层：全色波段 B8
var original_display = ls8.select(['B8']);

// 2) 保留原始输入作为基准版本
// original_display 直接作为基准版本使用

// 邻域核：半径 1 像元
var squareKernel = ee.Kernel.square({
  radius: 1,
  units: 'pixels',
  normalize: false
});

var circleKernel = ee.Kernel.circle({
  radius: 1,
  units: 'pixels',
  normalize: false
});

// 3) 构建处理链 A：先做轻度平滑降噪
var chain_a_smooth = original_display.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: squareKernel
});

// 4) 链 A：使用 Prewitt 算子提取线状细节
var kernel_a = ee.Kernel.prewitt();
var chain_a_stage = chain_a_smooth.convolve(kernel_a);

// 5) 链 A：再做一次中值滤波整理画面
var chain_a_final = chain_a_stage.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: circleKernel
});

// 6) 构建处理链 B：先做中值滤波邻域优化
var chain_b_smooth = original_display.reduceNeighborhood({
  reducer: ee.Reducer.median(),
  kernel: circleKernel
});

// 7) 链 B：使用四邻域 Laplacian 算子增强局部边界和纹理
var kernel_b = ee.Kernel.laplacian4();
var chain_b_stage = chain_b_smooth.convolve(kernel_b);

// 8) 链 B：再进行均值滤波，使画面更规整
var chain_b_final = chain_b_stage.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: squareKernel
});

// Collection 2 TOA 数据的 B8 反射率通常约为 0~1，
// 因此将原 OGE DN 范围调整为适用于 TOA 数据的显示范围。
var original_vis = {
  min: 0,
  max: 0.3,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

var enhance_vis = {
  min: -0.1,
  max: 0.1,
  palette: ['#1f1f1f', '#5a5a5a', '#9a9a9a', '#d9d9d9', '#ffffff']
};

// 9) 将原始结果、两套处理中间结果和最终结果添加到地图对照
Map.addLayer(original_display, original_vis, 'original_display');
Map.addLayer(chain_a_stage, enhance_vis, 'chain_a_stage');
Map.addLayer(chain_a_final, enhance_vis, 'chain_a_final');
Map.addLayer(chain_b_stage, enhance_vis, 'chain_b_stage');
Map.addLayer(chain_b_final, enhance_vis, 'chain_b_final');

// 设置地图中心
Map.setCenter(115.74080156644999, 31.7318082104, 11);

// 读取一景 Landsat 9 Collection 2 Level-2 反射率影像
var lc09 = ee.Image('LANDSAT/LC09/C02/T1_L2/LC09_122039_20230306');

// 1) 提取原始影像显示层（自然色）
var original_image = lc09.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 2) 为 NDVI 单独准备输入波段
var ndvi_input = lc09.select(['SR_B5', 'SR_B4']);

// 3) 转换为浮点型，便于后续计算
ndvi_input = ndvi_input.toFloat();

// 4) 计算常规植被指数 NDVI = (NIR - Red) / (NIR + Red)
var ndvi = ndvi_input.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

// 可视化参数
var original_vis = {
  min: 0,
  max: 30000
};

var ndvi_vis = {
  min: 0,
  max: 0.8,
  palette: ['#d9c27a', '#b8d16b', '#7fbf7b', '#3a924a', '#005a32']
};

// 5) 组织原始影像与指数结果的对照展示
Map.addLayer(original_image, original_vis, 'original_image');
Map.addLayer(ndvi, ndvi_vis, 'ndvi');

// 设置地图中心
Map.setCenter(115.35899045035, 30.296925757799997, 11);

// 读取一景 Landsat 9 Collection 2 Level-2 反射率影像
var lc09 = ee.Image('LANDSAT/LC09/C02/T1_L2/LC09_122039_20230306');

// 1) 提取原始影像显示层（自然色）
var original_image = lc09.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 2) 提取植被表达所需波段
var nir_band = lc09.select(['SR_B5']);
var red_band = lc09.select(['SR_B4']);

// 3) 转换为浮点型
original_image = original_image.toFloat();
nir_band = nir_band.toFloat();
red_band = red_band.toFloat();

// 4) 应用 Landsat 9 Level-2 地表反射率缩放
original_image = original_image.multiply(0.0000275).add(-0.2);
nir_band = nir_band.multiply(0.0000275).add(-0.2);
red_band = red_band.multiply(0.0000275).add(-0.2);

// 5) 计算常规植被指数 NDVI = (NIR - Red) / (NIR + Red)
var ndvi_num = nir_band.subtract(red_band);
var ndvi_den = nir_band.add(red_band);
var ndvi = ndvi_num.divide(ndvi_den).rename('NDVI');

// 6) 计算低覆盖区更稳的植被指数 SAVI
// SAVI = 1.5 * (NIR - Red) / (NIR + Red + 0.5)
var savi_den = ndvi_den.add(0.5);
var savi_base = ndvi_num.divide(savi_den);
var savi = savi_base.multiply(1.5).rename('SAVI');

// 7) 使用半径为 1 像素的圆形邻域均值进行平滑
var circleKernel = ee.Kernel.circle({
  radius: 1,
  units: 'pixels',
  normalize: false
});

ndvi = ndvi.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: circleKernel
}).rename('NDVI');

savi = savi.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: circleKernel
}).rename('SAVI');

// 可视化参数
var original_vis = {
  min: 0.0,
  max: 0.3
};

var veg_vis = {
  min: 0,
  max: 0.8,
  palette: ['#d9c27a', '#b8d16b', '#7fbf7b', '#3a924a', '#005a32']
};

// 8) 将原始影像、NDVI 和 SAVI 添加到地图
Map.addLayer(original_image, original_vis, 'original_image');
Map.addLayer(ndvi, veg_vis, 'ndvi');
Map.addLayer(savi, veg_vis, 'savi');

// 设置地图中心
Map.setCenter(115.35899045035, 30.296925757799997, 11);

// 读取一景 Landsat 9 Collection 2 Level-2 反射率影像
var lc09 = ee.Image('LANDSAT/LC09/C02/T1_L2/LC09_122039_20230306');

// 1) 提取原始影像显示层（自然色）
var original_image = lc09.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 2) 提取植被表达所需波段
var blue_band = lc09.select(['SR_B2']);
var red_band = lc09.select(['SR_B4']);
var nir_band = lc09.select(['SR_B5']);

// 3) 转换为浮点型
// original_image = original_image.toFloat();
blue_band = blue_band.toFloat();
red_band = red_band.toFloat();
nir_band = nir_band.toFloat();

// 4) 应用 Landsat 9 Collection 2 Level-2 地表反射率缩放
// original_image = original_image.toFloat().multiply(0.0000275).add(-0.2);
blue_band = blue_band.multiply(0.0000275).add(-0.2);
red_band = red_band.multiply(0.0000275).add(-0.2);
nir_band = nir_band.multiply(0.0000275).add(-0.2);

// 5) 计算常规植被指数 NDVI = (NIR - Red) / (NIR + Red)
var ndvi_num = nir_band.subtract(red_band);
var ndvi_den = nir_band.add(red_band);
var ndvi = ndvi_num.divide(ndvi_den).rename('NDVI');

// 6) 计算另一种植被状态表达结果 EVI
// EVI = 2.5 * (NIR - Red) / (NIR + 6 * Red - 7.5 * Blue + 1)
var red_scaled = red_band.multiply(6.0);
var blue_scaled = blue_band.multiply(7.5);

var evi_den = nir_band.add(red_scaled);
evi_den = evi_den.subtract(blue_scaled);
evi_den = evi_den.add(1.0);

var evi_base = ndvi_num.divide(evi_den);
var evi = evi_base.multiply(2.5).rename('EVI');

// 7) 对两种结果做统一范围整理
var veg_vis = {
  min: 0.0,
  max: 0.8,
  palette: ['8c510a', 'd8b365', 'f6e8c3', 'd9f0d3', '7fbf7b', '1b7837']
};

// 原始影像未按 OGE 示例进行缩放，因此显示参数使用 Landsat L2 原始 DN 范围。
var original_vis = {
  min: 7273,
  max: 43636,
  gamma: 1.2
};

// 8) 组织原始影像、两种植被结果及其对照结构
Map.addLayer(original_image, original_vis, 'original_image');
Map.addLayer(ndvi, veg_vis, 'ndvi');
Map.addLayer(evi, veg_vis, 'evi');

