var lc09 = ee.Image('LANDSAT/LC09/C02/T1_L2/LC09_122039_20230306');

// 1) 提取原始影像显示层（自然色）
var original_image = lc09.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 2) 为 MNDWI 单独准备输入波段
var mndwi_input = lc09.select(['SR_B3', 'SR_B6']);

// 3) 转换为浮点型
mndwi_input = mndwi_input.toFloat();

// 4) 应用 Landsat 9 Level-2 表面反射率缩放
mndwi_input = mndwi_input
  .multiply(0.0000275)
  .add(-0.2);

// 5) 计算 MNDWI = (Green - SWIR1) / (Green + SWIR1)
var mndwi = mndwi_input.normalizedDifference(['SR_B3', 'SR_B6']);

// 可视化参数
var original_vis = {};

var water_vis = {
  min: -0.5,
  max: 0.5,
  palette: ['#8c510a', '#d8b365', '#f6e8c3', '#c7eae5', '#5ab4ac', '#01665e']
};

// 6) 组织原始影像与水体结果的对照展示
Map.addLayer(original_image, original_vis, 'original_image');
Map.addLayer(mndwi, water_vis, 'mndwi');

// 设置地图中心
Map.setCenter(115.35899045035, 30.296925757799997, 11);

var lc09 = ee.Image('LANDSAT/LC09/C02/T1_L2/LC09_122039_20230306');

// 整体转浮点
var lc09_f = lc09.toFloat();

// 原始显示层
var original_image = lc09_f.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 整体做 L2 反射率缩放
var lc09_sr = lc09_f.multiply(0.0000275).add(-0.2);

// 直接计算 MNDWI
var mndwi = lc09_sr.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');

// 阈值提取：MNDWI × 100 >= 5，即 MNDWI >= 0.05
var mndwi_scaled = mndwi.multiply(100.0);
var water_mask = mndwi_scaled.gte(5).rename('water_mask');

// 使用 3 × 3 正方形邻域进行均值滤波
var water_result = water_mask.reduceNeighborhood({
  reducer: ee.Reducer.mean(),
  kernel: ee.Kernel.square(1, 'pixels', false)
}).rename('water_result');

var original_vis = {};

var water_index_vis = {
  min: -0.5,
  max: 0.5,
  palette: ['#8c510a', '#d8b365', '#f6e8c3', '#c7eae5', '#5ab4ac', '#01665e']
};

var water_mask_vis = {
  min: 0,
  max: 1,
  palette: ['#f5f5f5', '#5ab4ac']
};

Map.addLayer(original_image, original_vis, 'original_image');
Map.addLayer(mndwi, water_index_vis, 'mndwi');
Map.addLayer(water_result, water_mask_vis, 'water_result');

Map.setCenter(115.35899045035, 30.2969257578, 10);

// 读取一景 Landsat 9 Collection 2 Level-2 地表反射率影像
var lc09 = ee.Image(
  'LANDSAT/LC09/C02/T1_L2/LC09_L2SP_122039_20230306_20230308_02_T1'
);

// 1) 提取原始影像显示层（自然色）
var original_image = lc09.select(['SR_B4', 'SR_B3', 'SR_B2']);

// 2) 提取两类水体表达所需波段
var blue_band = lc09.select(['SR_B2']);
var green_band = lc09.select(['SR_B3']);
var nir_band = lc09.select(['SR_B5']);
var swir1_band = lc09.select(['SR_B6']);
var swir2_band = lc09.select(['SR_B7']);

// 3) 转换为浮点型
blue_band = blue_band.toFloat();
green_band = green_band.toFloat();
nir_band = nir_band.toFloat();
swir1_band = swir1_band.toFloat();
swir2_band = swir2_band.toFloat();

// 4) 应用 Landsat 9 Level-2 地表反射率缩放系数
blue_band = blue_band.multiply(0.0000275).add(-0.2);
green_band = green_band.multiply(0.0000275).add(-0.2);
nir_band = nir_band.multiply(0.0000275).add(-0.2);
swir1_band = swir1_band.multiply(0.0000275).add(-0.2);
swir2_band = swir2_band.multiply(0.0000275).add(-0.2);

// 5) 计算水体指数 A：MNDWI = (Green - SWIR1) / (Green + SWIR1)
var mndwi_num = green_band.subtract(swir1_band);
var mndwi_den = green_band.add(swir1_band);
var mndwi = mndwi_num.divide(mndwi_den).rename('MNDWI');

// 6) 计算水体指数 B：AWEIsh
// AWEIsh = Blue + 2.5*Green - 1.5*(NIR + SWIR1) - 0.25*SWIR2
var green_x25 = green_band.multiply(2.5);
