var combined_class = position_code.add(slope_class)
  .rename('combined_class');

// =========================
// 8. 地貌单元归并
// 1：谷地带；2：坡面带；3：山脊带；4：平坦过渡区
// =========================
var landform = ee.Image(0)
  .updateMask(combined_class.mask())
  .where(combined_class.eq(11), 1)
