  [40.5, 43.5, 4.0],

  [50.5, 52.5, 5.0],
  [52.5, 53.5, 4.0]
];

var slope_position = reclass(combined_class, slope_position_rules)
  .rename('slope_position');

// =========================
// 9. 去碎斑
